const headers = ($json && $json.headers) ? $json.headers : {};
const body = ($json && $json.body) ? $json.body : ($json ?? {});

const missing = [];
if (!String($env.GITLAB_WEBHOOK_SECRET || '').trim() && !String($env.GITLAB_WEBHOOK_SECRETS_JSON || '').trim() && !String($env.GITLAB_WEBHOOK_SECRETS_YAML || '').trim()) {
  missing.push('GITLAB_WEBHOOK_SECRET');
}
if (!String($env.N8N_ZULIP_API_BASE_URL || $env.ZULIP_BASE_URL || '').trim()) missing.push('ZULIP_BASE_URL');
if (!String($env.N8N_ZULIP_BOT_EMAIL || $env.ZULIP_BOT_EMAIL || '').trim()) missing.push('ZULIP_BOT_EMAIL');
if (!String($env.N8N_ZULIP_BOT_TOKEN || $env.ZULIP_BOT_TOKEN || $env.ZULIP_BOT_API_KEY || '').trim()) missing.push('ZULIP_BOT_API_KEY');

return [{
  json: {
    ok: missing.length === 0,
    status_code: missing.length === 0 ? 200 : 424,
    missing,
    received_event: String(headers['x-gitlab-event'] || headers['X-Gitlab-Event'] || body.object_kind || ''),
    tip: 'Issue Hook のラベル変更イベント（changes.labels）が届くことを確認してください。'
  }
}];
